import{_ as o,a0 as u,w as r,s as p,ao as x,I as i,a1 as l,A as s,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Linux是最好的操作系統嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux是最好的操作系統嗎？ | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux是最好的操作系統嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux是最好的操作系統嗎？ | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/Is Linux the best operating system","title":"Linux是最好的操作系統嗎？","tag":"201309","desc":""},"relativePath":"201309/Is Linux the best operating system.md","filePath":"[post].md"}'),a={name:"201309/Is Linux the best operating system.md"};function L(d,t,m,f,T,w){const e=u("Link");return r(),p("div",null,[t[14]||(t[14]=x('<h1 id="linux是最好的操作系統嗎" tabindex="-1">Linux是最好的操作系統嗎？ <a class="header-anchor" href="#linux是最好的操作系統嗎" aria-label="Permalink to “Linux是最好的操作系統嗎？”">​</a></h1><p>UVU Review 上有一篇稱Linux是最好的操作系統的文章。它包括以下幾個方面：</p><ul><li>價格</li><li>可用性</li><li>維護和修理</li><li>軟件和更新</li></ul><blockquote><p>無意冒犯，我認為我的同事們是錯的。Linux是手邊用來操作計算機的最佳選擇，甚至可以説沒什麼別的像樣的選擇。Neal Stephenson説過：“Mac電腦就像是密封式轎車，看起來很棒而且有不少廣告。安裝Windows的機器是龐大的SUV，經常壞，但到處都能見到它們並且人人會用。而Linux就像是免費的坦克一樣，在沼澤中每小時行駛90英里，1加侖油可以行駛100公里，並且不會出故障。”</p></blockquote><blockquote><p>我用Linux很多年了，從沒打算換系統。我們不能找出每一個證明它的優越性的理由，但我總結出了幾點。我假設你知道什麼是操作系統，同時明白Macintosh，Windows，和Linux都是不同的操作系統。</p></blockquote>',5)),i("blockquote",null,[i("p",null,[l(e,{href:"http://www.uvureview.com/2013/09/07/linux-is-clearly-the-superior-operating-system/"},{default:s(()=>[...t[0]||(t[0]=[n("UVU Review上的詳細內容",-1)])]),_:1})])]),t[15]||(t[15]=i("p",null,"作者提出強有力的理由來證明Linux的好。儘管我認同這篇文章的大多觀點，但我仍然很猶豫是否宣佈Linux為一個“最好”的操作系統。為什麼呢？選擇什麼操作系統和每個用户的需求息息相關。不同用户的選擇會大不一樣。",-1)),t[16]||(t[16]=i("p",null,"Linux可以很好地滿足用户的全部需求及其中的一部分。不過話説回來，也可能滿足不了。不去挖掘誰是適用的個體以及他們在使用計算機方面究竟有那些日常需要的話，很難概括這些東西。",-1)),t[17]||(t[17]=i("p",null,"某些情況下，一個全功能計算機可能不是用户的首選。移動設備已經很普及，用户可以通過移動設備使用收發郵件、瀏覽網頁等等之前只能由桌面計算機完成的功能。",-1)),t[18]||(t[18]=i("p",null,"這當然意味着可以使用Linux（Android, Firefox OS, Ubuntu），但他們也可能選擇iOS或者別的什麼移動設備操作系統。在移動設備領域，有不少非Linux的選擇，所以很可能Linux不會被用户使用，或者説是被錯過。",-1)),t[19]||(t[19]=i("p",null,"回到桌面來説，Linux明顯能被大量普及，我也總是推薦人們在虛擬機裏試試Linux以此來讓人們接觸Linux。但我也夠現實，知道這不是對每個人都適用。也許OS X 或者 Windows 更適合，這取決於用户的需求。",-1)),t[20]||(t[20]=i("p",null,"當你真正靜下心來想的時候，會發現很難界定什麼樣的操作系統是“最好”的。不論你怎樣定義，都不會影響他人。不過説到底Linux確實值得一試。如果你試試，你就可能會愛上Linux。",-1)),i("p",null,[t[3]||(t[3]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[1]||(t[1]=[n("LCTT",-1)])]),_:1}),t[4]||(t[4]=n(" 原創翻譯，",-1)),l(e,{href:"http://linux.cn/portal.php"},{default:s(()=>[...t[2]||(t[2]=[n("Linux中國",-1)])]),_:1}),t[5]||(t[5]=n(" 榮譽推出。",-1))]),i("p",null,[t[9]||(t[9]=n("譯者：",-1)),l(e,{href:"http://linux.cn/space/boredivan"},{default:s(()=>[...t[6]||(t[6]=[n("boredivan",-1)])]),_:1}),t[10]||(t[10]=n(" 校對：",-1)),l(e,{href:"http://linux.cn/space/caroline"},{default:s(()=>[...t[7]||(t[7]=[n("Caroline",-1)])]),_:1}),t[11]||(t[11]=n("，",-1)),l(e,{href:"http://linux.cn/space/wxy"},{default:s(()=>[...t[8]||(t[8]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=n("via: ",-1)),l(e,{href:"http://www.itworld.com/operating-systems/372109/linux-best-operating-system"},{default:s(()=>[...t[12]||(t[12]=[n("http://www.itworld.com/operating-systems/372109/linux-best-operating-system",-1)])]),_:1})])])}const y=o(a,[["render",L]]);export{g as __pageData,y as default};
